// recordQueueEntry is an entry in recordQueue.
type recordQueueEntry struct {
	p          []byte
	opts       SyncOptions
	refCount   RefCount
	writeStart crtime.Mono
}

type poppedEntry struct {
	opts       SyncOptions
	refCount   RefCount
	writeStart crtime.Mono
}

const initialBufferLen = 8192

// recordQueue is a variable-size single-producer multiple-consumer queue. It
// is not lock-free, but most operations only need mu.RLock. It needs a mutex
// to grow the size, since there is no upper bound on the number of queued
// records (which are all the records that are not synced, and will need to be
// written again in case of failover). Additionally, it needs a mutex to
// atomically grab a snapshot of the queued records and provide them to a new
// LogWriter that is being switched to.
type recordQueue struct {
	// Only held for reading for all pop operations and most push operations.
	// Held for writing when buffer needs to be grown or when switching to a new
	// writer.
	mu sync.RWMutex

	// queue is [tail, head). tail is the oldest entry and head is the index for
	// the next entry.
	//
	// Consumers: atomically read and write tail in pop. This is not the usual
	// kind of queue consumer since they already know the index that they are
	// popping exists, hence don't need to look at head.
	//
	// Producer: atomically reads tail in push. Writes to head.
	//
	// Based on the above we only need tail to be atomic. However, the producer
	// also populates entries in buffer, whose values need to be seen by the
	// consumers when doing a pop, which means they need to synchronize using a
	// release and acquire memory barrier pair, where the push does the release
	// and the pop does the acquire. For this reason we make head also atomic
	// and merge head and tail into a single atomic, so that the store of head
	// in push and the load of tail in pop accomplishes this release-acquire
	// pair.
	//
	// We initially implemented competition between multiple consumers solely
	// via atomic read-write of the tail using compare-and-swap (CAS). Since the
	// atomic read-write to tail in pop releases those buffer entries for reuse
	// to the producer, the consumer needs to grab the contents of
	// recordQueueEntry that it needs to do callbacks etc. (specifically the
	// contents corresponding to poppedEntry), *before* it succeeds with the
	// atomic read-write. This introduced a false data race in the Golang data
	// race detector
	// https://github.com/cockroachdb/pebble/issues/3380#issuecomment-1981188174.
	// Consider the case where the queue is [10,20), and consumer C1 is trying
	// to pop [10,12) and consumer C2 is trying to pop [10,14). The following
	// interleaving can happen:
	//
	// [C1] reads head=10, tail=20
	// [C2] reads head=10, tail=20
	// [C1] reads buffer contents [10,12) and makes local copy
	// [C1] CAS to make the queue [12,20)

// simply uses the concurrency limit retrieved from
// DBForCompaction.GetAllowedWithoutPermission to decide the number of
// compactions to schedule. ConcurrencyLimitScheduler must have its Register
// method called at most once -- i.e., it cannot be reused across DBs.
//
// Since the GetAllowedWithoutPermission value changes over time, the
// scheduler needs to be quite current in its sampling, especially if the
// value is increasing, to prevent lag in scheduling compactions. Calls to
// ConcurrencyLimitScheduler.Done and ConcurrencyLimitScheduler.TrySchedule
// are obvious places this value is sampled. However, since
// ConcurrencyLimitScheduler does not observe flushes (which can increase the
// value), and there can be situations where compactions last 10+ seconds,
// this sampling is not considered sufficient. Note that calls to
// ConcurrencyLimitScheduler.TrySchedule are dampened in
// DB.maybeScheduleCompaction when there is a waiting compaction (to prevent
// wasted computation of pickedCompaction). If DB.maybeScheduleCompaction
// always called ConcurrencyLimitScheduler.TrySchedule we would have no lag as
// DB.maybeScheduleCompaction is called on flush completion. Hence, we resort
// to having a background thread in ConcurrencyLimitScheduler sample the value
// every 100ms, plus sample in UpdateGetAllowedWithoutPermission.
type ConcurrencyLimitScheduler struct {
	ts schedulerTimeSource
	// db is set in Register, but not protected by mu since it is strictly
	// before any calls to the other methods.
	db DBForCompaction
	mu struct {
		sync.Mutex
		runningCompactions int
		// unregistered transitions once from false => true.
		unregistered bool
		// isGranting is used to (a) serialize granting from Done and
		// periodicGranter, (b) ensure that granting is stopped before returning
		// from Unregister.
		isGranting                   bool
		isGrantingCond               *sync.Cond
		lastAllowedWithoutPermission int
	}
	stopPeriodicGranterCh chan struct{}
	pokePeriodicGranterCh chan struct{}
	// Only non-nil in some tests.

	return o.KeyTypes != IterKeyTypePointsOnly && i.batch != nil && i.batch.batch.countRangeKeys > 0
}

// iteratorBatchState holds state pertaining to iterating over an indexed batch.
// When an iterator is configured to read through an indexed batch, the iterator
// maintains a pointer to this struct. This struct is embedded within the
// iterAlloc struct to reduce allocations.
type iteratorBatchState struct {
	batch *Batch
	// batchSeqNum is used by Iterators over indexed batches to detect when the
	// underlying batch has been mutated. The batch beneath an indexed batch may
	// be mutated while the Iterator is open, but new keys are not surfaced
	// until the next call to SetOptions.
	batchSeqNum base.SeqNum
	// batch{PointIter,RangeDelIter,RangeKeyIter} are used when the Iterator is
	// configured to read through an indexed batch. If a batch is set, these
	// iterators will be included within the iterator stack regardless of
	// whether the batch currently contains any keys of their kind. These
	// pointers are used during a call to SetOptions to refresh the Iterator's
	// view of its indexed batch.
	pointIter    batchIter
	rangeDelIter keyspan.Iter
	rangeKeyIter keyspan.Iter
	// pointInterleavingIter is the iterv2.InterleavingIter that wraps
	// pointIter and rangeDelIter at the batch level of the merging iterator
	// (iterv2 only; zero otherwise). It is held here so SetOptions can call
	// InvalidateCachedSpan after re-initializing rangeDelIter.
	pointInterleavingIter iterv2.InterleavingIter
}

